\label{def1}
	For function $f : \mathbb{R}^d \rightarrow \mathbb{R}$, we have
	\begin{itemize}
		\item $f$ is $L$-smooth if $f$ has continuous gradients and $\forall \, x, y \in \mathbb{R}^d$, it satisfies $|f(y)-f(x)-\langle\nabla f(x), y - x\rangle| \leq \frac{L}{2}||y-x||^2$.

		\item $f$ is convex if $\forall \, x, y \in \mathbb{R}^d$, it satisfies $f(y) \geq f(x) + \langle\nabla f(x), y - x\rangle $.

		\item $f$ is $\tau$-strongly-convex if $f(x)-\frac{\tau}{2}||x||^2$ is convex, \emph{i.e.}, $\forall \, x, y \in \mathbb{R}^d$, it satisfies $f(y) \geq f(x) + \langle\nabla f(x), y - x\rangle + \frac{\tau}{2}||y - x||^2$.
	\end{itemize}

\label{theorem2}
	Suppose Assumptions \ref{a2} and \ref{a3} hold. Denote $s_0=\lfloor\log n\rfloor+1$, set \[T_s=\begin{cases}
		2^{s-1},& s\leq s_0\\
		T_{s_0},& s> s_0\\
	\end{cases}, \; \alpha_s=\begin{cases}
		\frac{1}{2},& s\leq s_0\\[2pt]
		\min\left\{\sqrt{\frac{n}{4\varsigma}}, \frac{1}{2}\right\},& s> s_0\\
	\end{cases}\] \[p_s=\frac{1}{2}, \; \theta_t=\begin{cases}
		\Gamma_{t-1}-(1-\alpha_s-p_s)\Gamma_{t}, &t\leq T_s-1\\
		\Gamma_{t-1}, &t=T_{s}\\
	\end{cases}, \;\eta_{s,t}=\begin{cases}
		\frac{D_0}{sT_sL},& s\leq s_0\\[2pt]
		\frac{\left(\frac{4}{5}\right)^{s-s_0-1}D_0}{snL},& s>s_0 \textrm{ and } n\geq\varsigma\\[2pt]
		\frac{\left(\frac{1}{\Gamma_{T_{s_0}}}\right)^{s-s_0-1}D_0}{snL},& s>s_0 \textrm{ and } n<\varsigma\\
	\end{cases}\]
	where $\varsigma, \Gamma_{t}, D_0$ will be specified below for two cases respectively.

	$\bullet$ For the first-order case, set $\gamma_s=\frac{1}{3L\alpha_s}, \varsigma=\frac{3L}{4\tau}, \Gamma_{t}=\left(1+\tau\gamma_s\right)^{t}, D_0=4(f(\tilde{x}^0)-f(x^*))+3L\|x^0-x^*\|^2$. We have
	\[\begin{aligned}
		\mathbb{E}\left[f(\tilde{x}^{S})-f(x^*)\right]\leq \begin{cases}
			\frac{3D_0(\log S + 2)}{2^{S+1}},& s\leq s_0\\[2pt]
			\left(\frac{4}{5}\right)^{S-s_0}\frac{5D_0(\log S + 2)}{n},& s>s_0 \textrm{ and } n\geq\varsigma\\[2pt]
			\left(1+\frac{1}{2}\sqrt{\frac{n\tau}{3L}}\right)^{-(S-s_0)}\frac{5D_0(\log S + 2)}{n},& s>s_0 \textrm{ and } n<\varsigma\\
		\end{cases}
	\end{aligned}\]

	$\bullet$ For the zeroth-order case, set $\gamma_s=\frac{1}{12dL\alpha_s}, \varsigma=\frac{5L}{4\tau}, \Gamma_{t}=\left(1+\frac{\tau\gamma_s}{2}\right)^{t}, D_0=4(f(\tilde{x}^0)-f(x^*))+5L\|x^0-x^*\|^2$. We have
	\[\begin{aligned}
	\small 
		\mathbb{E}\left[f(\tilde{x}^{S})-f(x^*)\right] \leq\hspace{-0.08in}
		\begin{cases}
			\frac{5D_0(\log S + 2)}{2^{S+1}}+\frac{\mu^2L^2d\left(d+4\right)}{4\tau}+2\mu^2Ld,& s\leq s_0\\[2pt]
			\left(\frac{4}{5}\right)^{S-s_0}\frac{8D_0(\log S + 2)}{n}+\Delta_1^\mu,& s>s_0,\; n\geq\varsigma\\[2pt]
			\begin{aligned}
				\left(1+\frac{1}{4}\sqrt{\frac{n\tau}{5L}}\right)^{-(S-s_0)}&\frac{8D_0(\log S + 2)}{n}\\&+\Delta_2^\mu
			\end{aligned}
			,& s>s_0,\; n<\varsigma\\
		\end{cases}
	\end{aligned}\]
	where $\Delta_1^\mu = \frac{5\mu^2L^2d(d+4)}{\tau}+12\mu^2Ld, \Delta_2^\mu = \frac{5\mu^2L^2d(d+4)}{\tau}+4\mu^2Ld\left(1+2\sqrt{\frac{5L}{n\tau}}\right)$.

With parameters set in Theorem \ref{theorem2}, for \emph{strongly-convex} problems, we have ($\tilde{\mathcal{O}}$ hides a logarithmic factor)

	$\bullet$ For the first-order case, the gradient query complexity can be bounded as \[
	\begin{aligned}
	    N_{GQO}= \begin{cases}
		\tilde{\mathcal{O}}\left(n\log\left(\frac{D_0}{\epsilon}\right)\right), &\epsilon\geq \tilde{\mathcal{O}}(\frac{D_0}{n}) \textrm{ or } n\geq \varsigma\\[2pt]
		\tilde{\mathcal{O}}\left(n\log n+\sqrt{\frac{nL}{\tau}}\log\left(\frac{D_0}{n\epsilon}\right)\right), &\epsilon< \tilde{\mathcal{O}}(\frac{D_0}{n}) \textrm{ and } n< \varsigma\\
	\end{cases}
	\end{aligned}
	\]
	$\bullet$ For the zeroth-order case, the function query complexity can be bounded as \[
	\begin{aligned}
	    N_{FQO}= \begin{cases}
		\tilde{\mathcal{O}}\left(nd\log\left(\frac{D_0}{\epsilon}\right)\right), &\epsilon\geq\tilde{\mathcal{O}}(\frac{D_0}{n}) \textrm{ or } n\geq\varsigma\\[2pt]
		\tilde{\mathcal{O}}\left(nd\log n+d\sqrt{\frac{nL}{\tau}}\log\left(\frac{D_0}{n\epsilon}\right)\right), &\epsilon<\tilde{\mathcal{O}}(\frac{D_0}{n}) \textrm{ and } n<\varsigma
	\end{cases}
	\end{aligned}
	\]
	$\bullet$ For both cases, the linear oracle complexity can be bounded as \[N_{LO} = \begin{cases}
	   \tilde{\mathcal{O}}\left(\frac{1}{\epsilon^2}\right), &\epsilon\geq\tilde{\mathcal{O}}(D_0/n) \textrm{ or } n\geq\varsigma\\[2pt]
		\tilde{\mathcal{O}}\left(n^2 + \frac{n}{\epsilon}\right), &\epsilon<\tilde{\mathcal{O}}(D_0/n) \textrm{ and } n<\varsigma
	\end{cases}\]

\label{lemma1}
		For any $x\in\mathcal{C}$, we have
		\begin{equation}
		\begin{aligned}
		&\gamma_s\left[l_f(\underline{x}_t, x_t)-l_f(\underline{x}_t, x)\right] \\
		\leq& \frac{\gamma_s\tau}{2}\|x-x_t\|^2+\frac{1}{2}\|x-x_{t-1}\|^2-\frac{1+\gamma_s\tau}{2}\|x-x_t\|^2-\frac{1+\gamma_s\tau}{2}\|x_t-x_{t-1}^+\|^2-\gamma_s\langle\delta_t, x_t-x\rangle+\eta_{s,t}
		\end{aligned}
		\end{equation}

From Algorithm \ref{algo1}, we have $\langle\nabla h(x_t), x_t-x\rangle \leq \eta_{s,t}$ for any $x\in\mathcal{C}$. Observe that $h$ is $(1+\tau\gamma_s)$-strongly convex, then we have
		\begin{equation}	\label{l1eq1}
			h(x_t)-h(x)+\frac{1+\tau\gamma_s}{2}\|x-x_t\|^2\leq\langle\nabla h(x_t), x_t-x\rangle\leq\eta_{s,t}, \; \forall\, x\in C
		\end{equation}
		which is
		\begin{equation}	\label{l1eq2}
		\begin{aligned}
		&\gamma_s\left[\langle G_t, x_t\rangle+\frac{\tau}{2}\|x_t-\underline{x}_t\|^2\right]+\frac{1}{2}\|x_t-x_{t-1}\|^2 \\
		\leq& \gamma_s\left[\langle G_t, x\rangle+\frac{\tau}{2}\|x-\underline{x}_t\|^2\right]+\frac{1}{2}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2}\|x-x_t\|^2+\eta_{s,t}, \; \forall\, x\in C
		\end{aligned}
		\end{equation}
		Rearranging the terms, we get
		\begin{equation}	\label{l1eq3}
		\begin{aligned}
		&\gamma_s\left[\langle G_t, x_t-x\rangle+\frac{\tau}{2}\|x_t-\underline{x}_t\|^2\right]+\frac{1}{2}\|x_t-x_{t-1}\|^2 \\
		\leq& \frac{\gamma_s\tau}{2}\|x-x_t\|^2+\frac{1}{2}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2}\|x-x_t\|^2+\eta_{s,t}
		\end{aligned}
		\end{equation}
		With the notation of $l_f(\cdot, \cdot)$, we have
		\begin{equation}	\label{l1eq4}
		\begin{aligned}
		\langle G_t, x_t-x\rangle =& \langle \nabla f(\underline{x}_t), x_t-x\rangle+\langle\delta_t, x_t-x\rangle = l_f(\underline{x}_t, x_t)-l_f(\underline{x}_t, x)+\langle\delta_t, x_t-x\rangle\\
		\end{aligned}
		\end{equation}
		Also we have
		\begin{equation}	\label{l1eq5}
		\begin{aligned}
		&\frac{\gamma_s\tau}{2}\|x_t-\underline{x}_t\|^2+\frac{1}{2}\|x_t-x_{t-1}\|^2\\
		=&\frac{\gamma_s\tau}{2}\|x_t\|^2-\langle x_t, \gamma_s\tau\underline{x}_t\rangle +\frac{\gamma_s\tau}{2}\|\underline{x}_t\|^2+\frac{1}{2}\|x_t\|^2-\langle x_t, x_{t-1}\rangle +\frac{1}{2}\|x_{t-1}\|^2\\
		=&\frac{1+\gamma_s\tau}{2}\|x_t\|^2-(1+\gamma_s\tau)\langle x_t, \frac{1}{1+\gamma_s\tau}(\gamma_s\tau\underline{x}_t+x_{t-1})\rangle+\underbrace{\frac{\gamma_s\tau}{2}\|\underline{x}_t\|^2+\frac{1}{2}\|x_{t-1}\|^2}_{Q_1}\\
		\end{aligned}
		\end{equation}
		For the term $Q_1$, we have
		\begin{equation}	\label{l1eq6}
		\begin{aligned}
		2(1+\gamma_s\tau)Q_1=&(1+\gamma_s\tau)\left(\gamma_s\tau\|\underline{x}_t\|^2+\|x_{t-1}\|^2\right)\\
		=&\gamma_s\tau\|\underline{x}_t\|^2+\gamma_s\tau\|x_{t-1}\|^2+\left(\gamma_s^2\tau^2\|\underline{x}_t\|^2+\|x_{t-1}\|^2\right)\\
		=& \gamma_s\tau\|\underline{x}_t\|^2+\gamma_s\tau\|x_{t-1}\|^2-2\gamma_s\tau\langle \underline{x}_t, x_{t-1}\rangle+\|\gamma_s\tau\underline{x}_t+x_{t-1}\|^2
		\end{aligned}
		\end{equation}
		With the notation of $x_{t-1}^+$, we have
		\begin{equation}	\label{l1eq7}
		2(1+\gamma_s\tau)Q_1 \geq \|\gamma_s\tau\underline{x}_t+x_{t-1}\|^2 = (1+\gamma_s\tau)^2\|x_{t-1}^+\|^2
		\end{equation}
		which is
		\begin{equation}	\label{l1eq8}
		Q_1\geq \frac{1+\gamma_s\tau}{2}\|x_{t-1}^+\|^2
		\end{equation}
		Plugging (\ref{l1eq8}) into (\ref{l1eq5}), we get
		\begin{equation}	\label{l1eq9}
		\begin{aligned}
		&\frac{\gamma_s\tau}{2}\|x_t-\underline{x}_t\|^2+\frac{1}{2}\|x_t-x_{t-1}\|^2\\
		\geq& \frac{1+\gamma_s\tau}{2}\|x_t\|^2-(1+\gamma_s\tau)\langle x_t, \frac{1}{1+\gamma_s\tau}(\gamma_s\tau\underline{x}_t+x_{t-1})\rangle+\frac{1+\gamma_s\tau}{2}\|x_{t-1}^+\|^2 = \frac{1+\gamma_s\tau}{2}\|x_t-x_{t-1}^+\|^2
		\end{aligned}
		\end{equation}
		Plugging (\ref{l1eq4}) and (\ref{l1eq9}) into (\ref{l1eq3}) and rearranging the terms, we get
		\begin{equation}
		\begin{aligned}
		&\gamma_s\left[l_f(\underline{x}_t, x_t)-l_f(\underline{x}_t, x)\right] \\
		\leq& \frac{\gamma_s\tau}{2}\|x-x_t\|^2+\frac{1}{2}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2}\|x-x_t\|^2+\eta_{s,t}-\frac{1+\gamma_s\tau}{2}\|x_t-x_{t-1}^+\|^2-\gamma_s\langle\delta_t, x_t-x\rangle
		\end{aligned}
		\end{equation}
		Then we complete the proof.

Since $f$ is $\tau$-strongly convex and $L$-smooth, then we have
		\begin{equation}	\label{l2eq7}
		\begin{aligned}
		f(\bar{x}_t)\leq&l_{f}(\underline{x}_t,\bar{x}_t)+\frac{L}{2}\|\bar{x}_t-\underline{x}_t\|^2\\
		\overset{\textrm{\ding{172}}}{=}&(1-\alpha_s-p_s)l_{f}(\underline{x}_t,\bar{x}_{t-1})+\alpha_sl_{f}(\underline{x}_t,x_t)+p_sl_{f}(\underline{x}_t,\tilde{x})+\frac{L\alpha_s^2}{2}\|x_t-x_{t-1}^+\|^2
		\end{aligned}
		\end{equation}
		where \ding{172} comes from the definition of $\bar{x}_t$ in Algorithm \ref{algo1}. Plugging Lemma \ref{lemma1} into (\ref{l2eq7}), we get
		\begin{equation}	\label{l2eq1}
		\begin{aligned}
		f(\bar{x}_t)\leq&(1-\alpha_s-p_s)l_{f}(\underline{x}_t,\bar{x}_{t-1})\\
		&+\alpha_s\left[l_{f}(\underline{x}_t,x)+\frac{\tau}{2}\|x-\underline{x}_t\|^2+\frac{1}{2\gamma_s}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2\gamma_s}\|x-x_t\|^2+\frac{\eta_{s,t}}{\gamma_s}\right]\\
		&+p_sl_{f}(\underline{x}_t,\tilde{x})-\frac{\alpha_s}{2\gamma_s}\left(1+\tau\gamma_s-L\alpha_s\gamma_s\right)\|x_t-x_{t-1}^+\|^2-\alpha_s\langle\delta_t, x_t-x\rangle\\
		\overset{\textrm{\ding{172}}}{\leq}& (1-\alpha_s-p_s)f(\bar{x}_{t-1})+\alpha_s\left[f(x)+\frac{1}{2\gamma_s}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2\gamma_s}\|x-x_t\|^2+\frac{\eta_{s,t}}{\gamma_s}\right]\\
		&+p_sl_{f}(\underline{x}_t,\tilde{x})-\frac{\alpha_s}{2\gamma_s}\left(1+\tau\gamma_s-L\alpha_s\gamma_s\right)\|x_t-x_{t-1}^+\|^2-\alpha_s\langle\delta_t, x_t-x_{t-1}^+\rangle-\alpha_s\langle\delta_t, x_{t-1}^+-x\rangle\\
		\end{aligned}
		\end{equation}
		where \ding{172} comes from the fact that $f$ is $\tau$-strongly convex. Now we give proof to the first-order and zeroth-order case respectively.

		\textbf{First-order Case}: Using the fact that $b\langle u, v\rangle-a\|v\|^2/2\leq b^2\|u\|^2/(2a)$, we have from (\ref{l2eq1})
		\begin{equation}	\label{l2eq4}
		\begin{aligned}
		f(\bar{x}_t)\leq& (1-\alpha_s-p_s)f(\bar{x}_{t-1})+\alpha_s\left[f(x)+\frac{1}{2\gamma_s}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2\gamma_s}\|x-x_t\|^2+\frac{\eta_{s,t}}{\gamma_s}\right]\\
		&+\underbrace{p_sl_{f}(\underline{x}_t,\tilde{x})+\frac{\alpha_s\gamma_s\|\delta_t\|^2}{2(1+\tau\gamma_s-L\alpha_s\gamma_s)}-\alpha_s\langle\delta_t, x_{t-1}^+-x\rangle}_{Q_2}\\
		\end{aligned}
		\end{equation}
		Using Lemma \ref{lemma4}, we can bound $Q_2$ as
		\begin{equation}	\label{l2eq2}
		\begin{aligned}
		&\mathbb{E}\left[p_sl_{f}(\underline{x}_t,\tilde{x})+\frac{\alpha_s\gamma_s\|\delta_t\|^2}{2(1+\tau\gamma_s-L\alpha_s\gamma_s)}-\alpha_s\langle\delta_t, x_{t-1}^+-x\rangle\right] = \mathbb{E}\left[p_sl_{f}(\underline{x}_t,\tilde{x})+\frac{\alpha_s\gamma_s\|\delta_t\|^2}{2(1+\tau\gamma_s-L\alpha_s\gamma_s)}\right]\\
		\overset{\textrm{\ding{172}}}{\leq}&p_sl_{f}(\underline{x}_t,\tilde{x})+\frac{L\alpha_s\gamma_s}{1+\tau\gamma_s-L\alpha_s\gamma_s}\left(f(\tilde{x})-l_f(\underline{x}_t, \tilde{x})\right)\\
		=&\left(p_s-\frac{L\alpha_s\gamma_s}{2(1+\tau\gamma_s-L\alpha_s\gamma_s)}\right)l_{f}(\underline{x}_t,\tilde{x})+\frac{L\alpha_s\gamma_s}{1+\tau\gamma_s-L\alpha_s\gamma_s}f(\tilde{x}) \overset{\textrm{\ding{173}}}{\leq} p_sf(\tilde{x})
		\end{aligned}
		\end{equation}
		where \ding{172} comes from Lemma \ref{lemma4} and  \ding{173} comes from the assumption that $p_s-\frac{L\alpha_s\gamma_s}{1+\tau\gamma_s-L\alpha_s\gamma_s}>p_s-\frac{2L\alpha_s\gamma_s}{1+\tau\gamma_s-L\alpha_s\gamma_s}>0$ and the convexity of $f$. Plugging (\ref{l2eq2}) into (\ref{l2eq4}), we get
		\begin{equation}
		\begin{aligned}
		&\mathbb{E}\left[f(\bar{x}_t)+\frac{\alpha_s(1+\tau\gamma_s)}{2\gamma_s}\|x-x_t\|^2\right]\\
		\leq&(1-\alpha_s-p_s)f(\bar{x}_{t-1})+\alpha_sf(x)+p_sf(\tilde{x})+\frac{\alpha_s}{2\gamma_s}\|x-x_{t-1}\|^2+\frac{\alpha_s}{\gamma_s}\eta_{s,t}
		\end{aligned}
		\end{equation}
		Subtracting both sides with $f(x)$ and then multiplying both sides with $\frac{\gamma_s}{\alpha_s}$, we get
		\begin{equation}
		\begin{aligned}
		&\frac{\gamma_s}{\alpha_s}\mathbb{E}\left[f(\bar{x}_t)-f(x)\right]+\frac{1+\tau\gamma_s}{2}\mathbb{E}\left[\|x-x_t\|^2\right]\\
		\leq&\frac{\gamma_s(1-\alpha_s-p_s)}{\alpha_s}\left[f(\bar{x}_{t-1})-f(x)\right]+\frac{\gamma_sp_s}{\alpha_s}\left[f(\tilde{x})-f(x)\right]+\frac{1}{2}\|x-x_{t-1}\|^2+\eta_{s,t}
		\end{aligned}
		\end{equation}
		Then we get the desired result for the first-order case. Next we give proof to the zeroth-order case.

		\textbf{Zeroth-order Case}: We can rewrite (\ref{l2eq1}) as
		\begin{equation}	\label{l2eq6}
		\begin{aligned}
		f(\bar{x}_t)\leq& (1-\alpha_s-p_s)f(\bar{x}_{t-1})+\alpha_s\left[f(x)+\frac{1}{2\gamma_s}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2\gamma_s}\|x-x_t\|^2+\frac{\eta_{s,t}}{\gamma_s}\right]\\
		&+p_sl_{f}(\underline{x}_t,\tilde{x})-\frac{\alpha_s}{2\gamma_s}\left(1+\tau\gamma_s-L\alpha_s\gamma_s\right)\|x_t-x_{t-1}^+\|^2-\alpha_s\langle\delta_t-\mathbb{E}\left[\delta_t\right], x_t-x_{t-1}^+\rangle\\
		&-\alpha_s\langle\mathbb{E}\left[\delta_t\right], x_t-x_{t-1}^+\rangle-\alpha_s\langle\delta_t, x_{t-1}^+-x\rangle\\
		\overset{\textrm{\ding{172}}}{\leq}& (1-\alpha_s-p_s)f(\bar{x}_{t-1})+\alpha_s\left[f(x)+\frac{1}{2\gamma_s}\|x-x_{t-1}\|^2-\frac{1+\tau\gamma_s}{2\gamma_s}\|x-x_t\|^2+\frac{\eta_{s,t}}{\gamma_s}\right]\\
		&+p_sl_{f}(\underline{x}_t,\tilde{x})+\frac{\alpha_s\gamma_s\|\delta_t-\mathbb{E}\left[\delta_t\right]\|^2}{2(1+\tau\gamma_s-L\alpha_s\gamma_s)}-\alpha_s\langle\mathbb{E}\left[\delta_t\right], x_t-x_{t-1}^+\rangle-\alpha_s\langle\delta_t, x_{t-1}^+-x\rangle\\
		\end{aligned}
		\end{equation}
		where \ding{172} comes from the fact that $b\langle u, v\rangle-a\|v\|^2/2\leq b^2\|u\|^2/(2a)$. Using Lemma \ref{lemma4}, we have
		\begin{equation}	\label{l2eq3}
		\begin{aligned}
		&\mathbb{E}\left[p_sl_{f}(\underline{x}_t,\tilde{x})+\frac{\alpha_s\gamma_s\|\delta_t-\mathbb{E}\left[\delta_t\right]\|^2}{2(1+\tau\gamma_s-L\alpha_s\gamma_s)}\right]\\
		\overset{\textrm{\ding{172}}}{\leq}& p_sl_f(\underline{x}_t, \tilde{x})+\frac{4\alpha_s\gamma_sL}{1+\tau\gamma_s-L\alpha_s\gamma_s}\left(f(\tilde{x})-l_f(\underline{x}_t, \tilde{x})\right)+\frac{6\alpha_s\gamma_s\mu^2L^2d}{1+\tau\gamma_s-L\alpha_s\gamma_s}\\
		=&\left(p_s-\frac{4\alpha_s\gamma_sL}{1+\tau\gamma_s-L\alpha_s\gamma_s}\right)l_f(\underline{x}_t, \tilde{x})+\frac{4\alpha_s\gamma_sL}{1+\tau\gamma_s-L\alpha_s\gamma_s}f(\tilde{x})+\frac{6\alpha_s\gamma_s\mu^2L^2d}{1+\tau\gamma_s-L\alpha_s\gamma_s}\\
		\overset{\textrm{\ding{173}}}{\leq}& p_sf(\tilde{x})+\frac{6\alpha_s\gamma_s\mu^2L^2d}{1+\tau\gamma_s-L\alpha_s\gamma_s}\\
		\end{aligned}
		\end{equation}
		where \ding{172} comes from Lemma \ref{lemma4} and \ding{173} comes from the assumption that $p_s-\frac{4\alpha_s\gamma_sdL}{1+\tau\gamma_s-L\alpha_s\gamma_s}>0$ and the convexity of $f$. Also we have
		\begin{equation}	\label{l2eq5}
		\begin{aligned}
		&\mathbb{E}\left[-\alpha_s\langle\mathbb{E}\left[\delta_t\right], x_t-x_{t-1}^+\rangle-\alpha_s\langle\delta_t, x_{t-1}^+-x\rangle\right] = -\alpha_s\langle\hat{\nabla}_{coord}f(\underline{x}_t)-\nabla f(\underline{x}_t), x_t-x\rangle
		\end{aligned}
		\end{equation}
		which comes from Lemma \ref{lemma4}. Plugging (\ref{l2eq3}), (\ref{l2eq5}) into (\ref{l2eq6}), we get
		\begin{equation}
		\begin{aligned}
		&\mathbb{E}\left[f(\bar{x}_t)+\frac{\alpha_s(1+\tau\gamma_s)}{2\gamma_s}\|x-x_t\|^2\right]\\
		\leq&(1-\alpha_s-p_s)f(\bar{x}_{t-1})+\alpha_sf(x)+p_sf(\tilde{x})+\frac{\alpha_s}{2\gamma_s}\|x-x_{t-1}\|^2+\frac{\alpha_s}{\gamma_s}\eta_{s,t}\\
		&-\alpha_s\langle\hat{\nabla}_{coord}f(\underline{x}_t)-\nabla f(\underline{x}_t), x_t-x\rangle+\frac{6\alpha_s\gamma_s\mu^2L^2d}{1+\tau\gamma_s-L\alpha_s\gamma_s}\\
		\end{aligned}
		\end{equation}
		Subtracting both sides with $f(x)$ and then multiplying both sides with $\frac{\gamma_s}{\alpha_s}$, we get
		\begin{equation}
		\begin{aligned}
		&\frac{\gamma_s}{\alpha_s}\mathbb{E}\left[f(\bar{x}_t)-f(x)\right]+\frac{1+\tau\gamma_s}{2}\mathbb{E}\left[\|x-x_t\|^2\right]\\
		\leq&\frac{\gamma_s(1-\alpha_s-p_s)}{\alpha_s}\left[f(\bar{x}_{t-1})-f(x)\right]+\frac{\gamma_sp_s}{\alpha_s}\left[f(\tilde{x})-f(x)\right]+\frac{1}{2}\|x-x_{t-1}\|^2+\eta_{s,t}\\
