We give proof to the first-order case and zeroth-order case respectively.

		\textbf{First-order Case}: Lemma \ref{lemma8} implies
		\begin{equation}
		\begin{aligned}
		\mathcal{L}_s\mathbb{E}\left[f(\tilde{x}^s)-f(x)\right]
		\leq \mathcal{R}_s\mathbb{E}\left[f(\tilde{x}^{s-1})-f(x)\right]+\mathbb{E}\left[\frac{1}{2}\|x-x^{s-1}\|^2-\frac{1}{2}\|x-x^s\|^2\right] +\sum_{t=1}^{T_s}\eta_{s,t}\\
		\end{aligned}
		\end{equation}
		Summing the above inequality over $s = 1, ..., S$, and set $x=x^*=\arg\min_{x\in\mathcal{C}}f(x)$, we have
		\begin{equation}	\label{t1eq4}
		\begin{aligned}
		&\mathcal{L}_S\mathbb{E}\left[f(\tilde{x}^S)-f(x^*)\right]+\sum_{s=1}^{S-1}\left(\mathcal{L}_s-\mathcal{R}_{s+1}\right)\mathbb{E}\left[f(\tilde{x})-f(x^*)\right]\\
		\leq& \mathcal{R}_1\mathbb{E}\left[f(\tilde{x}^0)-f(x^*)\right]+\mathbb{E}\left[\frac{1}{2}\|x^*-x^0\|^2-\frac{1}{2}\|x^*-x^S\|^2\right] +\sum_{s=1}^S\sum_{t=1}^{T_s}\eta_{s,t}\\
		\end{aligned}
		\end{equation}
		Next we prove $\mathcal{L}_s-\mathcal{R}_{s+1}\leq0$ for all $s= 1, ..., S-1$. When $s< s_0$, we have $\alpha_{s+1}=\alpha_s=\frac{1}{2}, \gamma_{s+1}=\gamma_s, p_{s+1}=p_s=\frac{1}{2}, T_{s+1}=2T_s$, thus
		\begin{equation}
		\begin{aligned}
		\mathcal{L}_s-\mathcal{R}_{s+1} =&\frac{\gamma_s}{\alpha_s}+(T_s-1)\frac{\gamma_s(\alpha_s+p_s)}{\alpha_s}-\left[\frac{\gamma_{s+1}}{\alpha_{s+1}}(1-\alpha_{s+1})+(T_{s+1}-1)\frac{\gamma_{s+1}p_{s+1}}{\alpha_{s+1}}\right]\\ =&\frac{\gamma_s}{\alpha_s}\left[1+(T_s-1)(\alpha_s+p_s)-(1-\alpha_s)-(2T_s-1)p_s\right] = \frac{\gamma_s}{\alpha_s}\left[T_s(\alpha_s-p_s)\right] = 0
		\end{aligned}
		\end{equation}
		When $s\geq s_0$, we have $\alpha_s=\frac{2}{s-s_0+4}, \gamma_s=\frac{1}{3L\alpha_s}, p_{s+1}=p_s=\frac{1}{2}, T_{s+1}=T_s$, thus
		\begin{equation}
		\begin{aligned}
		\mathcal{L}_s-\mathcal{R}_{s+1}  =&\frac{\gamma_s}{\alpha_s}+(T_s-1)\frac{\gamma_s(\alpha_s+p_s)}{\alpha_s}-\left[\frac{\gamma_{s+1}}{\alpha_{s+1}}(1-\alpha_{s+1})+(T_{s+1}-1)\frac{\gamma_{s+1}p_{s+1}}{\alpha_{s+1}}\right]\\= &\frac{\gamma_s}{\alpha_s}-\frac{\gamma_{s+1}}{\alpha_{s+1}}(1-\alpha_{s+1})+(T_{s_0}-1)\left[\frac{\gamma_s(\alpha_s+p_s)}{\alpha_s}-\frac{\gamma_{s+1}p_{s+1}}{\alpha_{s+1}}\right]\\
