			\sum_{k=s_0+1}^S\left(\frac{1}{\Gamma_{T_{s_0}}}\right)^{S+1-k}\frac{2\alpha_s\sum_{t=1}^{T_s}\Gamma_{t-1}\eta_{k,t}}{\gamma_s\sum_{t=1}^{T_s}\Gamma_{t-1}}=&\sum_{k=s_0+1}^S\left(\frac{1}{\Gamma_{T_{s_0}}}\right)^{S-s_0}\frac{2}{kn}D_0\\\leq&\left(\frac{1}{\Gamma_{T_{s_0}}}\right)^{S-s_0}\frac{2(\log S + 1)}{n}D_0
		\end{aligned}
		\end{equation}
		Plugging (\ref{t2ceq18}), (\ref{t2ceq19}) into (\ref{t2ceq20}), we get
		\begin{equation}	\label{t2ceq21}
		\begin{aligned}
		\mathbb{E}\left[f(\tilde{x}^S)-f(x^*)\right] \leq&\left(\frac{1}{\Gamma_{T_{s_0}}}\right)^{S-s_0}\frac{3D_0(\log s_0 + 2)}{2^{s_0}}+\left(\frac{1}{\Gamma_{T_{s_0}}}\right)^{S-s_0}\frac{2(\log S + 1)}{n}D_0\\
		\overset{\textrm{\ding{172}}}{\leq}&\left(\frac{1}{\Gamma_{T_{s_0}}}\right)^{S-s_0}\frac{5D_0(\log S + 2)}{n}
		\end{aligned}
		\end{equation}
		where \ding{172} comes from $2^{s_0}\geq n$. From the definition of $\Gamma_{T_{s_0}}$, we have
		\begin{equation}	\label{t2ceq22}
		\Gamma_{T_{s_0}}=\left(1+\tau\gamma_s\right)^{T_{s_0}}\geq1+\tau\gamma_sT_{s_0}\geq1+\frac{\tau\gamma_s n}{2}=1+\frac{1}{2}\sqrt{\frac{n\tau}{3L}}
		\end{equation}
		Plugging (\ref{t2ceq22}) into (\ref{t2ceq21}), we get
		\begin{equation}
		\begin{aligned}
		&\mathbb{E}\left[f(\tilde{x}^S)-f(x^*)\right]
		\leq\left(1+\frac{1}{2}\sqrt{\frac{n\tau}{3L}}\right)^{-(S-s_0)}\frac{5D_0(\log S + 2)}{n}
		\end{aligned}
		\end{equation}
		Then we get the desired result for the first-order case.

		\textbf{Zeroth-order Case}: We have $\alpha_s=\sqrt{\frac{n\tau}{5L}}, p_s=\frac{1}{2}, \gamma_s=\frac{1}{\sqrt{5n\tau L}}, T_s=T_{s_0}=2^{s_0-1}$. Setting $c=\frac{1}{2}$ in Lemma \ref{lemma9}, we have
		\begin{equation}	\label{t2ceq1}
		\begin{aligned}
		&\frac{\gamma_s}{\alpha_s}\mathbb{E}\left[f(\bar{x}_t)-f(x)\right]+\frac{1+\frac{\tau\gamma_s}{2}}{2}\mathbb{E}\left[\|x-x_t\|^2\right]\\
		\leq&\frac{\gamma_s(1-\alpha_s-p_s)}{\alpha_s}\left[f(\bar{x}_{t-1})-f(x)\right]+\frac{\gamma_sp_s}{\alpha_s}\left[f(\tilde{x})-f(x)\right]+\frac{1}{2}\|x-x_{t-1}\|^2+\eta_{s,t}\\
		&+\frac{\gamma_s\mu^2L^2d}{\tau}+\frac{6\gamma_s^2\mu^2L^2d}{1+\tau\gamma_s-L\alpha_s\gamma_s}\\
		\leq&\frac{\gamma_s(1-\alpha_s-p_s)}{\alpha_s}\left[f(\bar{x}_{t-1})-f(x)\right]+\frac{\gamma_sp_s}{\alpha_s}\left[f(\tilde{x})-f(x)\right]+\frac{1}{2}\|x-x_{t-1}\|^2+\eta_{s,t}\\
		&+\frac{\gamma_s\mu^2L^2d}{\tau}+\frac{\gamma_s}{\alpha_s}\cdot\frac{3\mu^2Ld}{2}\\
		\end{aligned}
		\end{equation}
		Multiplying both sides of the inequality with $\Gamma_{t-1}=\left(1+\frac{\tau\gamma_s}{2}\right)^{t-1}$, we get
		\begin{equation}
		\begin{aligned}
		&\frac{\gamma_s}{\alpha_s}\Gamma_{t-1}\mathbb{E}\left[f(\bar{x}_t)-f(x)\right]+\frac{\Gamma_{t}}{2}\mathbb{E}\left[\|x-x_t\|^2\right]\\
		\leq&\frac{\gamma_s(1-\alpha_s-p_s)}{\alpha_s}\Gamma_{t-1}\left[f(\bar{x}_{t-1})-f(x)\right]+\frac{\gamma_sp_s}{\alpha_s}\Gamma_{t-1}\left[f(\tilde{x})-f(x)\right]+\frac{\Gamma_{t-1}}{2}\|x-x_{t-1}\|^2+\Gamma_{t-1}\eta_{s,t}\\
		&+\Gamma_{t-1}\frac{\gamma_s\mu^2L^2d}{\tau}+\Gamma_{t-1}\frac{\gamma_s}{\alpha_s}\cdot\frac{3\mu^2Ld}{2}\\
		\end{aligned}
		\end{equation}
		Summing up the inequality for $t=1, ..., T_s$, using the definition of $\theta_t$, we get
		\begin{equation}
		\begin{aligned}
		&\frac{\gamma_s}{\alpha_s}\sum_{t=1}^{T_s}\theta_{t}\mathbb{E}\left[f(\bar{x}_t)-f(x)\right]+\frac{\Gamma_{T_s}}{2}\mathbb{E}\left[\|x_{T_s}-x\|^2\right]\\
		\leq&\frac{\gamma_s}{\alpha_s}\left(1-\alpha_s-p_s+p_s\sum_{t=1}^{T_s}\Gamma_{t-1}\right)\left[f(\tilde{x})-f(x)\right]+\frac{1}{2}\|x_0-x\|^2+\sum_{t=1}^{T_s}\Gamma_{t-1}\eta_{s,t}\\
		&+\sum_{t=1}^{T_s}\Gamma_{t-1}\frac{\gamma_s\mu^2L^2d}{\tau}+\sum_{t=1}^{T_s}\Gamma_{t-1}\frac{\gamma_s}{\alpha_s}\cdot\frac{3\mu^2Ld}{2}\\
		\end{aligned}
		\end{equation}
		From the definition of $\tilde{x}^s, \tilde{x}^{s-1}, x^s, x^{s-1}$ and the convexity of $f$, we have
		\begin{equation}	\label{t2ceq6}
		\begin{aligned}
		&\frac{\gamma_s}{\alpha_s}\sum_{t=1}^{T_s}\theta_{t}\mathbb{E}\left[f(\tilde{x}^s)-f(x)\right]+\frac{\Gamma_{T_s}}{2}\mathbb{E}\left[\|x^s-x\|^2\right]\\
		\leq&\frac{\gamma_s}{\alpha_s}\left(1-\alpha_s-p_s+p_s\sum_{t=1}^{T_s}\Gamma_{t-1}\right)\left[f(\tilde{x}^{s-1})-f(x)\right]+\frac{1}{2}\|x^{s-1}-x\|^2+\sum_{t=1}^{T_s}\Gamma_{t-1}\eta_{s,t}\\
		&+\sum_{t=1}^{T_s}\Gamma_{t-1}\frac{\gamma_s\mu^2L^2d}{\tau}+\sum_{t=1}^{T_s}\Gamma_{t-1}\frac{\gamma_s}{\alpha_s}\cdot\frac{3\mu^2Ld}{2}\\
		\end{aligned}
		\end{equation}
		From the definition of $\theta_t$, we have
		\begin{equation}	\label{t2ceq4}
		\begin{aligned}
		\sum_{t=1}^{T_{s_0}}\theta_t=&\Gamma_{T_{s_0}-1}+\sum_{t=1}^{T_{s_0}-1}\left(\Gamma_{t-1}-(1-\alpha_s-p_s)\Gamma_{t}\right)\\
		=&\Gamma_{T_{s_0}}(1-\alpha_s-p_s)+\sum_{t=1}^{T_{s_0}}\left(\Gamma_{t-1}-(1-\alpha_s-p_s)\Gamma_{t}\right)\\
		=&\Gamma_{T_{s_0}}(1-\alpha_s-p_s)+\left[1-(1-\alpha_s-p_s)\left(1+\frac{\tau\gamma_s}{2}\right)\right]\sum_{t=1}^{T_{s_0}}\Gamma_{t-1}\\
		\end{aligned}
		\end{equation}
		Since $T_{s_0}=2^{s_0-1}\leq n$, we have
		\begin{equation}	\label{t2ceq2}
		\begin{aligned}
		\alpha_s=\sqrt{\frac{n\tau}{5L}}\geq\sqrt{\frac{T_{s_0}\tau}{5L}}=\frac{1}{\sqrt{5n\tau L}}\cdot\tau\sqrt{T_{s_0}n}\geq\tau\gamma_sT_{s_0}\geq\frac{\tau\gamma_s T_{s_0}}{2}
		\end{aligned}
		\end{equation}
		Then we have
		\begin{equation}	\label{t2ceq3}
		\begin{aligned}
		1-(1-\alpha_s-p_s)\left(1+\frac{\tau\gamma_s}{2}\right)=&\left(1+\frac{\tau\gamma_s}{2}\right)\left(\alpha_s+p_s-\frac{\tau\gamma_s}{2}\right)+\frac{\tau^2\gamma_s^2}{4}\\
