		=&p_s\left(1+\frac{\tau\gamma_s}{2}\right)\left(1+2(T_{s_0}-1)\frac{\tau\gamma_s}{2}\right)\\
		\overset{\textrm{\ding{173}}}{\geq}&p_s\left(1+\frac{\tau\gamma_s}{2}\right)^{T_{s_0}}=p_s\Gamma_{T_{s_0}}
