		\begin{equation}	\label{t2ceq7}
		\frac{\gamma}{\alpha}\left[1-\alpha-p+p\sum_{t=1}^{T_{s_0}}\Gamma_{t-1}\right]\geq\frac{\gamma p}{\alpha}\sum_{t=1}^{T_{s_0}}\Gamma_{t-1}\geq\frac{\gamma pT_{s_0}}{\alpha}
		\end{equation}
