		\begin{aligned}
		\mathbb{E}\left[f(\tilde{x}^S)-f(x^*)\right] \leq&\left(\frac{1}{\Gamma_{T_s}}\right)^{S-s_0}\left[\left[f(\tilde{x}^{s_0})-f(x^*)\right]+\frac{\alpha}{\gamma T_{s_0}}\|x^{s_0}-x^*\|^2\right]\\
		&+\sum_{k=s_0+1}^S\left(\frac{1}{\Gamma_{T_s}}\right)^{S+1-k}\left[\frac{2\alpha\sum_{t=1}^{T_s}\Gamma_{t-1}\eta_{k,t}}{\gamma\sum_{t=1}^{T_s}\Gamma_{t-1}} +\frac{2\alpha\mu^2L^2d}{\tau}+3\mu^2Ld\right]\\
