			=& (1-\alpha_{s,t})f(\bar{x}_{t-1})+\alpha_{s,t}f(x^*)+\alpha_{s,t}\langle G_t, x_t-x^*\rangle+\frac{L\alpha_{s,t}^2}{2}\|x_t-x_{t-1}\|^2 + \alpha_{s,t}\langle \delta_t, x^*-x_t\rangle\\
			\overset{\textrm{\ding{174}}}{\leq}&(1-\alpha_{s,t})f(\bar{x}_{t-1})+\alpha_{s,t}f(x^*)+\frac{\alpha_{s,t}}{\gamma_{s,t}}\eta_{s,t} - \frac{\alpha_{s,t}}{\gamma_{s,t}}\langle x_t-x_{t-1}, x_t-x^*\rangle\\&+\frac{L\alpha_{s,t}^2}{2}\|x_t-x_{t-1}\|^2 + \alpha_{s,t}\langle \delta_t, x^*-x_t\rangle\\
			=&(1-\alpha_{s,t})f(\bar{x}_{t-1})+\alpha_{s,t}f(x^*)+\frac{\alpha_{s,t}}{\gamma_{s,t}}\eta_{s,t} + \frac{\alpha_{s,t}}{2\gamma_{s,t}}\left(\|x_{t-1}-x^*\|^2-\|x_t-x^*\|^2\right)\\&+\frac{\alpha_{s,t}}{2}\left[\left(L\alpha_{s,t}-\frac{1}{\gamma_{s,t}}\right)\|x_t-x_{t-1}\|^2 + 2\langle \delta_t, x_{t-1}-x_t\rangle + 2\langle \delta_t, x^*-x_{t-1}\rangle\right]\\
			\overset{\textrm{\ding{175}}}{\leq}&(1-\alpha_{s,t})f(\bar{x}_{t-1})+\alpha_{s,t}f(x^*)+\frac{\alpha_{s,t}}{\gamma_{s,t}}\eta_{s,t} + \frac{\alpha_{s,t}}{2\gamma_{s,t}}\left(\|x_{t-1}-x^*\|^2-\|x_t-x^*\|^2\right)\\&+\frac{\alpha_{s,t}}{2}\left[\frac{\gamma_{s,t}\|\delta_t\|^2}{1-L\alpha_{s,t}\gamma_{s,t}} + 2\langle \delta_t, x^*-x_{t-1}\rangle\right]\\
		\end{aligned}
	\end{equation}
	where \ding{172} comes from the definition of $\underline{x}_t$ and $x_t$, \ding{173} comes from the convexity of $f$, \ding{174} comes from Line \ref{condg} of Algorithm \ref{storc}, \ding{175} comes from the fact that $b\langle u, v\rangle-a\|v\|^2/2\leq b^2\|u\|^2/(2a)$. Note that $\mathbb{E}\left[\langle \delta_t, x^*-x_{t-1}\rangle\right] = 0$. So with the condition $\mathbb{E}\left[\|\delta_t\|^2\|\right]\leq\frac{L^2D_s^2}{T_s(k+1)^2} \overset{\textrm{def}}{=} \sigma_t^2$ we arrive at
	\begin{equation}
		\begin{aligned}
			&\mathbb{E}\left[f(\bar{x}_t)-f(x^*)\right]\\
			\leq& (1-\alpha_{s,t})\mathbb{E}\left[f(\bar{x}_{t-1})-f(x^*)\right] \\&+ \alpha_{s,t}\left[\frac{1}{\gamma_{s,t}}\eta_{s,t} + \frac{1}{2\gamma_{s,t}}\left(\mathbb{E}\left[\|x_{t-1}-x^*\|^2\right]-\mathbb{E}\left[\|x_t-x^*\|^2\right]\right) + \frac{\gamma_{s,t}\sigma_t^2}{2\left(1-L\alpha_{s,t}\gamma_{s,t}\right)}\right]
		\end{aligned}
	\end{equation}
	Now we define $\Gamma_{t} = \Gamma_{t-1}\left(1-\alpha_{s,t}\right)$ when $t>1$ and $\Gamma_1 = 1$. By induction, one can verify $\Gamma_{t} = \frac{2}{t(t+1)}$ and the following:
	\begin{equation}
		\begin{aligned}
			&\mathbb{E}\left[f(\bar{x}_t)-f(x^*)\right]\\
			\leq& \Gamma_{t}\sum_{k=1}^{t}\frac{\alpha_{s,k}}{\Gamma_k}\left[\frac{1}{\gamma_{s,k}}\eta_{s,k} + \frac{1}{2\gamma_{s,k}}\left(\mathbb{E}\left[\|x_{k-1}-x^*\|^2\right]-\mathbb{E}\left[\|x_k-x^*\|^2\right]\right) + \frac{\gamma_{s,k}\sigma_k^2}{2\left(1-L\alpha_{s,k}\gamma_{s,k}\right)}\right]
		\end{aligned}
	\end{equation}
	which is at most
	\begin{equation}	\label{key}
		\begin{aligned} &\Gamma_{t}\sum_{k=1}^{t}\frac{\alpha_{s,k}}{\Gamma_k}\left[\frac{1}{\gamma_{s,k}}\eta_{s,k} + \frac{\gamma_{s,k}\sigma_k^2}{2\left(1-L\alpha_{s,k}\gamma_{s,k}\right)}\right]\\ &+ \frac{\Gamma_t}{2}\left[\frac{\alpha_{s,1}}{\gamma_{s,1}\Gamma_1}\mathbb{E}\left[\|x_0-x^*\|^2\right]+\sum_{k=2}^{t}\left(\frac{\alpha_{s,k}}{\gamma_{s,k}\Gamma_k}-\frac{\alpha_{s,k-1}}{\gamma_{s,k-1}\Gamma_{k-1}}\right)\mathbb{E}\left[\|x_{k-1}-x^*\|^2\right]\right]
		\end{aligned}
	\end{equation}
	Finally plugging in the parameters $\alpha_{s,k}, \gamma_{s,k}, \eta_{s,k}, \Gamma_k$ and the bound $\mathbb{E}\left[\|\bar{x}_0-x^*\|^2\right] \leq D_s^2$ concludes the proof:
	\begin{equation}
		\begin{aligned}
			&\mathbb{E}\left[f(\bar{x}_t)-f(x^*)\right]\leq\frac{2}{t(t+1)}\sum_{k=1}^{t}k\left[\frac{2LD_s^2}{T_sk} + \frac{LD_s^2}{2T_s(k+1)}\right] + \frac{3LD_s^2}{t(t+1)} \leq \frac{8LD_s^2}{t(t+1)}
		\end{aligned}
	\end{equation}
